    "package bptree",
    "",
    "import \"sync\"",
    "",
    "// frame is one buffer pool frame: a cached page plus its logical latch.",
    "//",
    "// Invariants:",
    "//   - latch is held by a caller only while pin > 0 (latch => pinned),",
    "//     so an eviction victim is never a latched frame.",
    "//   - release order is: latch Unlock first, then Unpin.",
    "type frame struct {",
    "\tpageID   PageID       // invalidPageID when unused",
    "\tpin      int          // guarded by pool.mu",
    "\tdirty    bool         // guarded by pool.mu on unpin/flush",
    "\tlastUsed uint64       // LRU tick, guarded by pool.mu",
    "\tlatch    sync.RWMutex // logical page latch",
    "\tdata     [PageSize]byte",
    "}",
    "",
    "type bufferPool struct {",
    "\tmu     sync.Mutex",
    "\tdisk   *diskManager",
    "\tframes [BufferPoolFrames]frame",
    "\ttable  map[PageID]int // pageID -> frame index",
    "\ttick   uint64         // LRU clock",
    "}",
    "",
    "func newBufferPool(disk *diskManager) *bufferPool {",
    "\tbp := &bufferPool{disk: disk, table: make(map[PageID]int)}",
    "\tfor i := range bp.frames {",
    "\t\tbp.frames[i].pageID = invalidPageID",
    "\t}",
    "\treturn bp",
    "}",
    "",
    "// fetch pins and returns the frame holding page pid, reading it from disk on",
    "// a miss (evicting an unpinned LRU frame if needed). The caller must then",
    "// latch the frame before touching data, and Unpin after unlocking.",
    "//",
    "// fetch only takes pool.mu briefly; it never acquires page latches, so it is",
    "// safe to call while holding page latches or metaMu.",
    "func (bp *bufferPool) fetch(pid PageID) (*frame, error) {",
    "\tbp.mu.Lock()",
    "\tdefer bp.mu.Unlock()",
    "",
    "\tif idx, ok := bp.table[pid]; ok {",
    "\t\tf := &bp.frames[idx]",
    "\t\tf.pin++",
    "\t\tf.touch(bp)",
    "\t\treturn f, nil",
    "\t}",
    "",
    "\tvictim := -1",
    "\tfor i := range bp.frames {",
    "\t\tf := &bp.frames[i]",
    "\t\tif f.pin == 0 && (victim < 0 || f.lastUsed < bp.frames[victim].lastUsed) {",
    "\t\t\tvictim = i",
    "\t\t}",
    "\t}",
    "\tif victim < 0 {",
    "\t\treturn nil, ErrNoFreeFrame",
    "\t}",
    "\tf := &bp.frames[victim]",
    "\tif f.pageID != invalidPageID {",
    "\t\tif f.dirty {",
    "\t\t\tif err := bp.disk.writePage(f.pageID, &f.data); err != nil {",
    "\t\t\t\treturn nil, err",
    "\t\t\t}",
    "\t\t}",
    "\t\tdelete(bp.table, f.pageID)",
    "\t}",
    "\tif err := bp.disk.readPage(pid, &f.data); err != nil {",
    "\t\t// Keep the frame out of the table but free for reuse.",
    "\t\tf.pageID = invalidPageID",
    "\t\tf.dirty = false",
    "\t\tf.lastUsed = 0",
    "\t\treturn nil, err",
    "\t}",
    "\tf.pageID = pid",
    "\tf.dirty = false",
    "\tf.pin = 1",
    "\tbp.table[pid] = victim",
    "\tf.touch(bp)",
    "\treturn f, nil",
    "}",
    "",
    "// unpin releases the caller's pin. Pass dirty=true if the page was modified.",
    "// Callers must unpin after releasing the page latch, never before.",
    "func (bp *bufferPool) unpin(f *frame, dirty bool) {",
    "\tbp.mu.Lock()",
    "\tdefer bp.mu.Unlock()",
    "\tif f.pin <= 0 {",
    "\t\tpanic(\"bptree: unpin of unpinned frame\")",
    "\t}",
    "\tf.pin--",
    "\tif dirty {",
    "\t\tf.dirty = true",
    "\t}",
    "}",
    "",
    "// flushAll writes every dirty resident page back to disk. Called from Close",
    "// when no operation is in flight.",
    "func (bp *bufferPool) flushAll() error {",
    "\tbp.mu.Lock()",
    "\tdefer bp.mu.Unlock()",
    "\tfor i := range bp.frames {",
    "\t\tf := &bp.frames[i]",
    "\t\tif f.pageID != invalidPageID && f.dirty {",
    "\t\t\tif err := bp.disk.writePage(f.pageID, &f.data); err != nil {",
    "\t\t\t\treturn err",
    "\t\t\t}",
    "\t\t\tf.dirty = false",
    "\t\t}",
    "\t}",
    "\treturn nil",
    "}",
    "",
    "func (f *frame) touch(bp *bufferPool) {",
    "\tbp.tick++",
    "\tf.lastUsed = bp.tick",
    "}"
