    "package bptree",
    "",
    "import \"errors\"",
    "",
    "// PageSize is the fixed on-disk page size in bytes.",
    "const PageSize = 8192",
    "",
    "// pageSlots is the number of int64 slots that fit in a page.",
    "// Every page is treated as an array of pageSlots int64 values.",
    "const pageSlots = PageSize / 8",
